arguments.command:
set -e
cat > /etc/nginx/sites-available/default << 'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/ssl/certs/nginx-selfsigned.crt;
    ssl_certificate_key /etc/ssl/private/nginx-selfsigned.key;

    location / {
        root /git/project/main;
        index index.html;
    }

    location /dev {
        root /git/project;
        index index.html;
    }
}
EOF
echo "---updated config---"
cat /etc/nginx/sites-available/default
echo "---nginx -t---"
nginx -t 2>&1
echo "---reload nginx---"
nginx -s reload 2>&1
sleep 1
echo "---nginx running?---"
pgrep -a nginx | head -1

